    Module = apps.get_model('catalog', 'Module')
    ModuleDefinition = apps.get_model('catalog', 'ModuleDefinition')
    for offering in Module.objects.order_by('semester__academic__start_date', 'semester__semester_no'):
        definition, _created = ModuleDefinition.objects.get_or_create(
            code=offering.module_code.strip().upper(),
            defaults={'name': offering.module_name},
        )
        if definition.name != offering.module_name:
            definition.name = offering.module_name
            definition.save(update_fields=['name'])
        offering.definition_id = definition.pk
        offering.save(update_fields=['definition'])


